@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500&family=Plus+Jakarta+Sans:wght@400;500;600&display=swap');

:root {
  --theme-color-primary: #3B5249;
  --theme-color-primary-content: #FAF8F5;
  --theme-color-secondary: #C87D6A;
  --theme-color-secondary-content: #FFFFFF;
  --theme-color-accent: #D4A359;
  --theme-color-accent-content: #1E2420;
  --theme-color-neutral: #262A27;
  --theme-color-neutral-content: #F5F2EB;
  --theme-color-surface: #FAF8F5;
  --theme-color-surface-alt: #F1EDE6;
  --theme-color-border: #E2DCD2;
  --theme-color-text: #242925;
  --theme-font-heading: 'Cormorant Garamond', Georgia, serif;
  --theme-font-body: 'Plus Jakarta Sans', system-ui, sans-serif;
  --theme-radius: 0.75rem;
}
